import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { useState, useCallback } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import mammoth from 'mammoth';
import jsPDF from 'jspdf';

pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

export interface AnalysisResult {
  fileName: string;
  score: number;
  date: string;
  categories: {
    keywords: number;
    skills: number;
    experience: number;
    education: number;
    formatting: number;
  };
  foundKeywords: string[];
  missingKeywords: string[];
  recommendations: string[];
}

export function useATSAnalysis() {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);

  const extractTextFromFile = async (file: File): Promise<string> => {
    const ext = file.name.split('.').pop()?.toLowerCase();
    if (ext === 'pdf') {
      const arrayBuffer = await file.arrayBuffer();
      const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
      let text = '';
      for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const content = await page.getTextContent();
        text += content.items.map((item: any) => item.str).join(' ') + ' ';
      }
      return text;
    } else if (ext === 'docx') {
      const arrayBuffer = await file.arrayBuffer();
      const { value } = await mammoth.extractRawText({ arrayBuffer });
      return value;
    } else {
      return await file.text();
    }
  };

  const analyzeResume = async (file: File, jobDescription: string) => {
    setIsAnalyzing(true);
    try {
      const resumeText = await extractTextFromFile(file);
      const lowerResume = resumeText.toLowerCase();

      // Extract potential keywords from job description (alphanumeric words > 3 chars)
      const jdWords = Array.from(new Set(
        jobDescription.toLowerCase().match(/\b[a-z]{4,}\b/g) || []
      ));

      const commonStopWords = new Set(['with', 'this', 'that', 'from', 'have', 'your', 'will', 'are', 'our', 'their']);
      const filteredJdWords = jdWords.filter(w => !commonStopWords.has(w));

      const foundKeywords: string[] = [];
      const missingKeywords: string[] = [];

      filteredJdWords.forEach(word => {
        if (lowerResume.includes(word)) {
          foundKeywords.push(word);
        } else {
          missingKeywords.push(word);
        }
      });

      const keywordMatchRatio = filteredJdWords.length > 0 
        ? foundKeywords.length / filteredJdWords.length 
        : 0;

      const keywordScore = Math.round(keywordMatchRatio * 100);

      // Additional heuristic scoring categories
      const hasEmail = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/.test(resumeText);
      const hasPhone = /\b\d{3}[-. ]?\d{3}[-. ]?\d{4}\b/.test(resumeText);
      const formattingScore = (hasEmail ? 50 : 20) + (hasPhone ? 50 : 20);

      const hasExperienceSection = /experience|employment|work history/i.test(resumeText);
      const experienceScore = hasExperienceSection ? 85 : 40;

      const hasEducationSection = /education|university|college|degree|bachelor|master|phd/i.test(resumeText);
      const educationScore = hasEducationSection ? 90 : 50;

      const skillKeywords = ['react', 'typescript', 'javascript', 'node', 'python', 'sql', 'tailwind', 'aws', 'docker', 'git'];
      const matchedSkills = skillKeywords.filter(s => lowerResume.includes(s));
      const skillsScore = Math.min(100, Math.round((matchedSkills.length / Math.max(1, skillKeywords.filter(s => jobDescription.toLowerCase().includes(s)).length)) * 100));

      const overallScore = Math.round(
        (keywordScore * 0.4) + 
        (skillsScore * 0.25) + 
        (experienceScore * 0.15) + 
        (educationScore * 0.1) + 
        (formattingScore * 0.1)
      );

      const recommendations: string[] = [];
      if (missingKeywords.length > 0) {
        recommendations.push(`Add missing key terms to your resume: ${missingKeywords.slice(0, 5).join(', ')}.`);
      }
      if (!hasEmail || !hasPhone) {
        recommendations.push('Ensure your contact email and phone number are clearly visible in plain text.');
      }
      if (!hasExperienceSection) {
        recommendations.push('Include a dedicated "Work Experience" section with clear job titles.');
      }
      if (keywordScore < 60) {
        recommendations.push('Tailor your resume bullet points to closely mirror phrasing from the job description.');
      } else {
        recommendations.push('Great keyword alignment! Ensure your accomplishments highlight measurable impact.');
      }

      const analysisResult: AnalysisResult = {
        fileName: file.name,
        score: Math.max(10, Math.min(100, overallScore)),
        date: new Date().toLocaleDateString(),
        categories: {
          keywords: keywordScore,
          skills: skillsScore,
          experience: experienceScore,
          education: educationScore,
          formatting: formattingScore,
        },
        foundKeywords,
        missingKeywords,
        recommendations,
      };

      setResult(analysisResult);

      // Save to localStorage history
      const existingHistory = JSON.parse(localStorage.getItem('ats_scan_history') || '[]');
      localStorage.setItem('ats_scan_history', JSON.stringify([analysisResult, ...existingHistory]));

    } catch (err) {
      console.error(err);
      alert('Failed to parse resume file.');
    } finally {
      setIsAnalyzing(false);
    }
  };

  const exportPDF = () => {
    if (!result) return;
    const doc = new jsPDF();
    doc.setFontSize(20);
    doc.text('ATS Resume Analysis Report', 20, 20);
    doc.setFontSize(12);
    doc.text(`File: ${result.fileName}`, 20, 30);
    doc.text(`Overall ATS Score: ${result.score}%`, 20, 40);
    doc.text(`Date: ${result.date}`, 20, 50);
    doc.text('Category Breakdown:', 20, 65);
    doc.text(`- Keywords: ${result.categories.keywords}%`, 25, 75);
    doc.text(`- Skills: ${result.categories.skills}%`, 25, 85);
    doc.text(`- Experience: ${result.categories.experience}%`, 25, 95);
    doc.text(`- Education: ${result.categories.education}%`, 25, 105);
    doc.text(`- Formatting: ${result.categories.formatting}%`, 25, 115);
    doc.text('Top Recommendations:', 20, 135);
    result.recommendations.forEach((rec, idx) => {
      doc.text(`${idx + 1}. ${rec}`, 25, 145 + (idx * 10));
    });
    doc.save(`${result.fileName}-ats-report.pdf`);
  };

  return { analyzeResume, isAnalyzing, result, exportPDF };
}

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface ScoreCategories {
  keywords: number;
  skills: number;
  experience: number;
  education: number;
  formatting: number;
}

interface ATSScoreChartProps {
  categories: ScoreCategories;
}

export const ATSScoreChart: React.FC<ATSScoreChartProps> = ({ categories }) => {
  const data = [
    { name: 'Keywords', score: categories.keywords },
    { name: 'Skills', score: categories.skills },
    { name: 'Experience', score: categories.experience },
    { name: 'Education', score: categories.education },
    { name: 'Formatting', score: categories.formatting },
  ];

  return (
    <div className="w-full h-72 bg-slate-900 border border-slate-800 rounded-xl p-4 shadow-xl">
      <h3 className="text-slate-200 font-semibold mb-4 text-sm uppercase tracking-wider">Score Breakdown</h3>
      <ResponsiveContainer width="100%" height="85%">
        <BarChart data={data} layout="vertical" margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
          <XAxis type="number" domain={[0, 100]} stroke="#64748b" />
          <YAxis dataKey="name" type="category" stroke="#94a3b8" width={90} />
          <Tooltip 
            contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', borderRadius: '0.5rem', color: '#f8fafc' }} 
          />
          <Bar dataKey="score" radius={[0, 4, 4, 0]}>
            {data.map((entry, index) => (
              <Cell 
                key={`cell-${index}`} 
                fill={entry.score >= 70 ? '#10b981' : entry.score >= 40 ? '#f59e0b' : '#ef4444'} 
              />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};
